#!/usr/bin/env bash
# P0-D: provision a REAL upstream WordPress install for smoke tests.
# Source is never modified (deployment config only: wp-config.php generated by
# wp-cli, options set in the database). Idempotent: skips when installed.
# Requires: php + mysql reachable + wp-cli (`wp` on PATH or $WP_CLI).
# Env: PHPX_WORDPRESS_DIR (default data/smoke/wordpress),
#      PHPX_WP_DB_HOST/PORT/NAME/USER/PASS (defaults 127.0.0.1/13306/wordpress/wp/wp),
#      PHPX_WP_URL (default http://127.0.0.1:18312, must match the test gateway port).
set -euo pipefail
DIR="${PHPX_WORDPRESS_DIR:-data/smoke/wordpress}"
DBHOST="${PHPX_WP_DB_HOST:-127.0.0.1}"
DBPORT="${PHPX_WP_DB_PORT:-13306}"
DBNAME="${PHPX_WP_DB_NAME:-wordpress}"
DBUSER="${PHPX_WP_DB_USER:-wp}"
DBPASS="${PHPX_WP_DB_PASS:-wp}"
URL="${PHPX_WP_URL:-http://127.0.0.1:18312}"
WP="${WP_CLI:-wp}"
export WP_CLI_SUPPRESS_GLOBAL_PARAMS=1

# Fixed canary post asserted by p0d_wordpress (idempotent by title).
ensure_canary_post() {
  if ! "$WP" post list --path="$DIR" --post_type=post --fields=post_title --format=csv 2>/dev/null | grep -q "Hello PHPX Smoke"; then
    "$WP" post create --path="$DIR" --post_type=post --post_title="Hello PHPX Smoke" --post_name=hello-phpx-smoke --post_content="PHPX smoke canary post." --post_status=publish >/dev/null
  fi
}

# Application password for authenticated REST tests (media upload, wc/v3).
# Stored deployment-side; tests read the file, never the DB.
ensure_app_password() {
  if [ ! -f "$DIR/.phpx-app-password" ]; then
    UUID=$("$WP" user application-password list admin --fields=uuid,name --format=csv --path="$DIR" 2>/dev/null | grep ',phpx-smoke$' | cut -d, -f1 || true)
    if [ -n "$UUID" ]; then
      "$WP" user application-password delete admin "$UUID" --path="$DIR" >/dev/null 2>&1 || true
    fi
    "$WP" user application-password create admin phpx-smoke --porcelain --path="$DIR" > "$DIR/.phpx-app-password" 2>/dev/null || rm -f "$DIR/.phpx-app-password"
  fi
}

if [ -f "$DIR/wp-config.php" ] && "$WP" core is-installed --path="$DIR" 2>/dev/null; then
  echo "[wp-smoke] already installed at $DIR ($("$WP" core version --path="$DIR" 2>/dev/null || echo version-unknown))"
  ensure_app_password
  ensure_canary_post
  exit 0
fi
command -v php >/dev/null || { echo "php not found in PATH"; exit 2; }
if ! command -v "$WP" >/dev/null && [ "$WP" = "wp" ]; then
  echo "wp-cli not found (set WP_CLI); Linux CI downloads it, Windows: C:/wp-cli/wp.bat"
  exit 2
fi
mkdir -p "$DIR"
if [ ! -f "$DIR/wp-includes/version.php" ]; then
  echo "[wp-smoke] downloading WordPress..."
  curl -sSL https://wordpress.org/latest.zip -o /tmp/wordpress-latest.zip
  unzip -q -o /tmp/wordpress-latest.zip -d /tmp/wp-smoke-tmp
  cp -r /tmp/wp-smoke-tmp/wordpress/. "$DIR/"
  rm -rf /tmp/wp-smoke-tmp /tmp/wordpress-latest.zip
fi
if [ ! -f "$DIR/wp-config.php" ]; then
  "$WP" config create --path="$DIR" --dbname="$DBNAME" --dbuser="$DBUSER" \
    --dbpass="$DBPASS" --dbhost="$DBHOST:$DBPORT" --skip-check --force
  "$WP" config set WP_ENVIRONMENT_TYPE local --path="$DIR" 2>/dev/null || true
fi
if ! "$WP" core is-installed --path="$DIR" 2>/dev/null; then
  "$WP" core install --path="$DIR" --url="$URL" --title="PHPX Smoke" \
    --admin_user=admin --admin_password=admin --admin_email=smoke@phpx.test --skip-email
fi
"$WP" rewrite structure '/%postname%/' --path="$DIR" --hard 2>/dev/null || \
  "$WP" rewrite structure '/%postname%/' --path="$DIR"
# P1-B integration: auto-approve comments so the comment round-trip test needs
# no wp-cli at test time (writes are observed via the REST API only).
for opt in comment_moderation comment_whitelist comment_previously_approved; do
  "$WP" option update "$opt" 0 --path="$DIR" >/dev/null 2>&1 || true
done
ensure_app_password
ensure_canary_post
echo "[wp-smoke] ready at $DIR ($("$WP" core version --path="$DIR")) url=$URL"
